  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(1201, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Parmi les facteurs de risque parentaux pour la survenue d’une LCH un seul n’est pas correcte lequel', '[{"l":"A","t":"Hérédité","c":false},{"l":"B","t":"Un accouchement par césarienne","c":true},{"l":"C","t":"Une présentation de siège","c":false},{"l":"D","t":"Une primiparité maternelle","c":false},{"l":"E","t":"Une prématurité","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1202, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Quelles sont les circonstances devant lesquelles il faut impérativement chercher une luxation congénitale de la hanche? (cochez la ou les réponses justes)', '[{"l":"A","t":"Toute présentation de siège","c":false},{"l":"B","t":"Oligohydramnios","c":true},{"l":"C","t":"Malposition des pieds","c":false},{"l":"D","t":"Gémellité","c":true},{"l":"E","t":"Retard de croissance intra utérin","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1203, 14, 'Chirurgie pédiatrique', 'Malformations congénitales du pied chez l’enfant', NULL, false, true, 'Parmi les propositions suivantes laquelle ou lesquelles) désignent un pied bot: (cochez les réponses justes)', '[{"l":"A","t":"Pied varus équin","c":true},{"l":"B","t":"Pied convexe","c":true},{"l":"C","t":"Pied plat","c":false},{"l":"D","t":"Pied talus","c":false},{"l":"E","t":"Pied creux","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1204, 14, 'Chirurgie pédiatrique', 'Malformations congénitales du pied chez l’enfant', NULL, false, true, 'Sur une radiographie du pied de face stricte en cas de pied bot varus équin, la diminution de la divergence talo-calcanéenne témoigne de : (cocher la ou les réponses justes)', '[{"l":"A","t":"L’adduction de l’avant pied","c":false},{"l":"B","t":"L’équinisme talo-calcanéen","c":false},{"l":"C","t":"L’adduction du bloc calcanéo pédieux","c":false},{"l":"D","t":"Le varus du calcanéum","c":true},{"l":"E","t":"L’équinisme tibio-calcanéen","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1205, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'Devant une déviation rachidienne quels éléments permettent de poser le diagnostic d’une scoliose ? (Cocher la ou les réponses justes)', '[{"l":"A","t":"Présence d’une gibbosité.","c":true},{"l":"B","t":"Douleurs rachidiennes.","c":false},{"l":"C","t":"Rotation vertébrale à la radiographie de face.","c":true},{"l":"D","t":"Correction de la déformation en anté-flexion","c":false},{"l":"E","t":"Déséquilibre du tronc.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1206, 25, 'Traumatologie', 'Fracture diaphysaire des deux os de l’avant-bras', NULL, false, true, 'L’Examen clinique d’un enfant présentant une paralysie obstétricale du plexus brachial peut retrouver :', '[{"l":"A","t":"une abduction et rotation interne du bras en cas d’atteinte C5-C6","c":false},{"l":"B","t":"une pronation de l’avant-bras","c":true},{"l":"C","t":"une légère flexion du coude en rapport avec la paralysie du triceps en cas d’atteinte C5-C6","c":false},{"l":"D","t":"un pouce à l’intérieur de la main en cas d’atteinte de Totale","c":true},{"l":"E","t":"une tête qui se détourne de la lésion","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1207, 17, 'Traumatologie', 'Maladies luxantes de la hanche', NULL, false, true, 'Sur une radiographie du bassin de face stricte, en cas de suspicion de LCH :', '[{"l":"A","t":"il y a un retard d’apparition des noyaux de ossification","c":true},{"l":"B","t":"angle acétabulaire augmenté témoignant de la luxation de hanche","c":false},{"l":"C","t":"la projection des noyaux épiphysaires dans le cadrant inféro-externe témoigne de la luxation de la hanche","c":true},{"l":"D","t":"le cintre cervico-obturateur rompu signe la luxation de hanche","c":false},{"l":"E","t":"la construction de putti est utilisée dès l’apparition des noyaux d’ossification","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1208, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Une luxation congénitale de la hanche non traitée aboutit à :', '[{"l":"A","t":"Une boiterie","c":true},{"l":"B","t":"Une douleur","c":false},{"l":"C","t":"Une infection","c":false},{"l":"D","t":"Une pseudarthrose","c":false},{"l":"E","t":"Une atteinte nerveuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1209, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Le diagnostic de luxation congénitale de la hanche doit être fait :', '[{"l":"A","t":"A la naissance","c":true},{"l":"B","t":"A l’âge de 6 mois","c":false},{"l":"C","t":"A l’âge de 1 an","c":false},{"l":"D","t":"A l’âge de 2 ans","c":false},{"l":"E","t":"A l’âge de la marche","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1210, 10, 'Rhumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', NULL, false, true, 'Le traitement du rachitisme est :', '[{"l":"A","t":"La chirurgie","c":false},{"l":"B","t":"Le traitement médical","c":true},{"l":"C","t":"L’immobilisation","c":false},{"l":"D","t":"La traction","c":false},{"l":"E","t":"La kinésithérapie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1211, 17, 'Traumatologie', 'Maladies luxantes de la hanche', NULL, false, true, 'Le diagnostic de luxation congénitale de la hanche est fait par :', '[{"l":"A","t":"Le scanner","c":false},{"l":"B","t":"L’IRM","c":false},{"l":"C","t":"L’échographie de la hanche","c":true},{"l":"D","t":"La radiographie du bassin","c":false},{"l":"E","t":"La scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1212, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Le “signe du télescope” est un signe de :', '[{"l":"A","t":"Luxation réductible","c":false},{"l":"B","t":"Luxation irréductible","c":true},{"l":"C","t":"Dysplasie","c":false},{"l":"D","t":"Instabilité","c":false},{"l":"E","t":"Lésion nerveuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1213, 17, 'Autre', 'Maladies luxantes de la hanche', NULL, false, true, 'L’examen clinique du nouveau-né doit inclure systématiquement :', '[{"l":"A","t":"La radiographie de la hanche","c":false},{"l":"B","t":"L’échographie de la hanche","c":true},{"l":"C","t":"Le scanner","c":false},{"l":"D","t":"L’IRM","c":false},{"l":"E","t":"La scintigraphie osseuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1214, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Le dépistage de la luxation congénitale de la hanche est :', '[{"l":"A","t":"Systématique","c":true},{"l":"B","t":"Optionnel","c":false},{"l":"C","t":"Fait seulement en cas de facteur de risque","c":false},{"l":"D","t":"Fait seulement en cas de signe clinique","c":false},{"l":"E","t":"Fait seulement en cas d’antécédent familial","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1215, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'La luxation congénitale de la hanche est plus fréquente chez :', '[{"l":"A","t":"Les garçons","c":false},{"l":"B","t":"Les filles","c":true},{"l":"C","t":"Les enfants nés par césarienne","c":false},{"l":"D","t":"Les enfants de petite taille","c":false},{"l":"E","t":"Les enfants de grande taille","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1216, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Le signe clinique le plus important pour le diagnostic de luxation congénitale de la hanche est :', '[{"l":"A","t":"L’asymétrie des plis cutanés","c":false},{"l":"B","t":"Le signe d’Ortolani et le signe de Barlow","c":true},{"l":"C","t":"La boiterie","c":false},{"l":"D","t":"L’inégalité de longueur des membres","c":false},{"l":"E","t":"Le signe du télescope","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1217, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Pour prévenir l''installation des escarres, toutes ces mesures sont justes sauf deux, lesquelles ?', '[{"l":"A","t":"Changement périodique de position","c":false},{"l":"B","t":"Régime hypercalorique hyperprotéique","c":false},{"l":"C","t":"Acidification des urines (vit C) et changement régulier des sondes urinaires.","c":true},{"l":"D","t":"Traitement anticoagulant à dose préventive","c":true},{"l":"E","t":"Hygiène corporelle et de la literie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1218, 7, 'MPR', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Chez un malade atteint de la Covid-19 installé en décubitus ventral à l’unité de soins Intensifs, les localisations les plus vulnérables pour développer des escarres sont :', '[{"l":"A","t":"Occiput","c":false},{"l":"B","t":"Epines iliaques antérosupérieures","c":true},{"l":"C","t":"Front.","c":true},{"l":"D","t":"Sacrée et talons","c":false},{"l":"E","t":"Tubérosités tibiales antérieures","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1219, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'Dans le cadre de prévention des complications respiratoires d’alimentation prolongée, la kinésithérapie respiratoire est basée sur :', '[{"l":"A","t":"Des séances d’aérosol","c":true},{"l":"B","t":"Retourlements, Klapping","c":true},{"l":"C","t":"Le drainage bronchique par posture.","c":true},{"l":"D","t":"Exercice de la mobilité et d’expansion de la cage thoracique","c":true},{"l":"E","t":"Intubation endotrachéale, parfois trachéotomie.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1220, 18, 'MPR', 'Amputations des membres', NULL, false, true, 'après une amputation du membre inférieur,toutes ces complications sont fréquements retrouvées sauf une la quelle :', '[{"l":"A","t":"Les sensations fantômes","c":false},{"l":"B","t":"nevromes douleureux","c":false},{"l":"C","t":"un hématome du moignon","c":false},{"l":"D","t":"une déhiscense de la plaie","c":false},{"l":"E","t":"des phlycténes","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1221, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'L’algoneurodystrophie (SDRC) est une complication :', '[{"l":"A","t":"Immédiate","c":false},{"l":"B","t":"Précoce","c":false},{"l":"C","t":"Tardive","c":true},{"l":"D","t":"Liée à une luxation","c":false},{"l":"E","t":"Liée à une infection","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1222, 8, 'Rhumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'La raideur articulaire est une complication :', '[{"l":"A","t":"Immédiate","c":false},{"l":"B","t":"Précoce","c":false},{"l":"C","t":"Tardive","c":true},{"l":"D","t":"Liée à une infection","c":false},{"l":"E","t":"Liée à une mauvaise réduction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1223, 29, 'Rhumatologie', 'Algoneurodystrophie', NULL, false, true, 'L’algoneurodystrophie est une complication :', '[{"l":"A","t":"Immédiate","c":false},{"l":"B","t":"Précoce","c":false},{"l":"C","t":"Tardive","c":true},{"l":"D","t":"Liée à une infection","c":false},{"l":"E","t":"Liée à un trouble neurologique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1224, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'rachidiennes 1 Quel est le principal examen pour dépister la scoliose ?', '[{"l":"A","t":"L’IRM","c":false},{"l":"B","t":"La radiographie de la colonne vertébrale","c":true},{"l":"C","t":"Test et mesure de l’angle de Cobb","c":false},{"l":"D","t":"L’examen de la mobilité articulaire","c":false},{"l":"E","t":"L’échographie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1225, 23, 'Chirurgie pédiatrique', 'Déviations rachidiennes : scoliose, cyphose', NULL, false, true, 'Lors de l’examen clinique d’une scoliose, lequel (lesquels) des points suivants est(sont) essentiel(s) pour évaluer la gravité de la déformation :', '[{"l":"A","t":"L’évaluation de l’angle de Cobb par radiographie","c":true},{"l":"B","t":"L’observation de la symétrie des épaules et des hanches","c":true},{"l":"C","t":"La mesure de la flexion du genou","c":false},{"l":"D","t":"L’évaluation de la mobilité thoracique","c":false},{"l":"E","t":"La vérification de la posture assise","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
