(1227, 20, 'Rhumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', NULL, false, true, 'La tendinopathie non rompue du supra épineux se caractérise par : (cochez la ou les. réponses justes)', '[{"l":"A","t":"Un tableau clinique d’une épaule pseudo paralytique","c":false},{"l":"B","t":"La mobilité passive est toujours limitée","c":false},{"l":"C","t":"La manœuvre de jobe est douloureuse","c":true},{"l":"D","t":"La manœuvre de jobe est déficitaire et indolore","c":false},{"l":"E","t":"La manœuvre de patte est douloureuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1228, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'Le diagnostic d’une fracture de l’extrémité supérieure de l’humérus est fait par :', '[{"l":"A","t":"Une IRM","c":false},{"l":"B","t":"Une échographie","c":false},{"l":"C","t":"Une radiographie de l’épaule de face et de profil","c":true},{"l":"D","t":"Une scintigraphie osseuse","c":false},{"l":"E","t":"Un scanner","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1229, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'L’articulation acromio-claviculaire est une articulation :', '[{"l":"A","t":"Diarthrose","c":true},{"l":"B","t":"Amphiarthrose","c":false},{"l":"C","t":"Synarthrose","c":false},{"l":"D","t":"Synostose","c":false},{"l":"E","t":"Symphyse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
