(1231, 6, 'Rhumatologie', 'Arthrose (hanche, genou)', NULL, false, true, 'L’arthrose de l’épaule est une maladie :', '[{"l":"A","t":"Inflammatoire","c":false},{"l":"B","t":"Dégénérative","c":true},{"l":"C","t":"Infectieuse","c":false},{"l":"D","t":"Métabolique","c":false},{"l":"E","t":"Neurologique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
