(1233, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'Le test de Skinner dans les fractures bimaléolaire permet', '[{"l":"A","t":"d’apprécier le centrage de l’astragale par-rapport a la pince malléolaire","c":false},{"l":"B","t":"il témoigne de l’axe du tibia par rapport à l’astragale","c":false},{"l":"C","t":"il mesure la longueur du péroné","c":true},{"l":"D","t":"il apprécie la hauteur de la mortaise tibio-péronière","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1234, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'Une fracture bimaléolaire par abduction- pure :', '[{"l":"A","t":"elle est classée type II de Duparc et Alnot","c":true},{"l":"B","t":"entraîne une supination du pied","c":false},{"l":"C","t":"entraîne un coup de hache externe péronier","c":false},{"l":"D","t":"malléole interne menaçant la peau","c":false},{"l":"E","t":"respecte l’intégrité de la syndessnose","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1235, 39, 'Rhumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'La fracture bimalleolaire par adduction est : (cocher la ou les réponses fausses)', '[{"l":"A","t":"comporte une lésion de la syndésmose","c":false},{"l":"B","t":"le mécanisme est direct","c":true},{"l":"C","t":"le traitement est orthopédique","c":true},{"l":"D","t":"le trait de fracture sur le péroné est sus tuberculaire","c":false},{"l":"E","t":"s’accompagne d’une lésion du sciatique poplité externe (SPE)","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1236, 39, 'Rhumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'La fracture bimaléolaire chez l’adulte est :', '[{"l":"A","t":"la fracture bimalleolaire la plus fréquente","c":false},{"l":"B","t":"survient suite à un mécanisme en éversion","c":false},{"l":"C","t":"le trait sur la malléole interne est vertical","c":false},{"l":"D","t":"pas de lésion de la syndesmose","c":false},{"l":"E","t":"le trait sur le péroné est sus-tuberculaire","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
