(1240, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', NULL, false, true, 'Le traitement d’une fracture bi-malléolaire non déplacée est :', '[{"l":"A","t":"La chirurgie","c":false},{"l":"B","t":"L’immobilisation plâtrée","c":true},{"l":"C","t":"La traction continue","c":false},{"l":"D","t":"Le traitement fonctionnel","c":false},{"l":"E","t":"La pose d’un fixateur externe","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
